      "rank": 1,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and geometric phase reveal that quantum behavior depends on more than local forces and have reshaped understanding across atomic, optical, and condensed-matter physics.",
        "attribution": "Aharonov's work established the physical importance of electromagnetic potentials; Berry identified the geometric phase acquired under adiabatic evolution. The distinct, complementary contributions support both names.",
        "maturity": "These ideas have been tested and applied for decades, with extensive experimental confirmation and broad influence.",
        "uncertainties": [
          "The discovery label joins related but historically distinct contributions, so the precise scope of a prize would need to be defined."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "Electron recollision made intense-field laser physics a powerful way to probe and control atomic-scale dynamics, underpinning high-harmonic generation and much of modern strong-field science.",
        "attribution": "Corkum articulated the recollision picture connecting ionization and return of the electron to observable radiation; Lewenstein developed a quantitative theoretical framework that made the mechanism predictive and widely useful.",
        "maturity": "The framework has been validated across many experiments and systems over several decades, and the field has developed substantially beyond its initial demonstrations.",
        "uncertainties": [
          "The discovery's boundaries overlap with adjacent developments in high-harmonic generation and attosecond science, complicating a compact attribution."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that fragile quantum information can, in principle, be protected, transforming the conceptual prospects for quantum computation and expanding the physics of topological codes.",
        "attribution": "Shor and Steane independently established landmark error-correcting codes, while Kitaev developed influential topological approaches that linked error protection to phases of matter. The credit spans distinct foundational advances.",
        "maturity": "The theory is firmly established, and experimental platforms have demonstrated increasingly capable error correction, though large-scale fault-tolerant operation remains unrealized.",
        "uncertainties": [
          "The breadth of the field makes it difficult to represent its many theoretical and experimental contributions within a small laureate group."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought atomic timekeeping into a regime of exceptional precision and opened new tests of fundamental physics, including sensitive comparisons of clocks and measurements of gravitational redshift.",
        "attribution": "Katori introduced the lattice-clock approach using a magic wavelength to suppress key systematic shifts; Ye led complementary advances in precision spectroscopy and clock implementation.",
        "maturity": "Independent clock systems and laboratories have confirmed the central performance gains, and the technology has become a mature precision-measurement platform.",
        "uncertainties": []
      }
    },
    {
      "rank": 5,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave strongly correlated electrons a practical framework for understanding local many-body physics and has become central to the study of materials beyond simple band theory.",
        "attribution": "Vollhardt and colleagues established the infinite-dimensional limit underlying the method; Georges and Kotliar helped formulate and develop its modern computational and conceptual framework. The credited names represent complementary foundational roles.",
        "maturity": "The method has been refined, benchmarked, and applied for decades across a broad range of correlated systems.",
        "uncertainties": [
          "The discovery is collective and its development involved a wider community than the three credited names."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Carlton M. Caves",
        "H. Jeff Kimble",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light demonstrates how quantum states can improve measurement beyond the usual shot-noise limit, with deep consequences for precision interferometry and gravitational-wave detection.",
        "attribution": "Caves established the theoretical case for quantum-enhanced interferometry; Kimble advanced experimental quantum optics and squeezed-state methods; Schnabel contributed major work bringing squeezed light into precision interferometry.",
        "maturity": "Squeezed light is now deployed in gravitational-wave observatories, following sustained experimental development and clear demonstrations of measurement benefit.",
        "uncertainties": [
          "The advance spans foundational theory, laboratory demonstrations, and large-scale detector implementation, making the boundaries of the prize contribution consequential."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B057",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry makes matter-wave phase a precise probe of acceleration, gravity, and fundamental interactions, extending interference methods to increasingly sensitive measurements.",
        "attribution": "Bordé established foundational atom-interferometry methods; Kasevich advanced influential precision measurements with atom interferometers. Both contributions helped turn the principle into a broadly useful experimental technique.",
        "maturity": "The method has been demonstrated in multiple laboratories and developed into a robust precision-measurement toolkit, although its most ambitious applications are still progressing.",
        "uncertainties": [
          "The field has many important contributors, and the credited group may not capture the full history of its development."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed a tunable setting for correlated quantum matter and has stimulated a large new body of experimental and theoretical work.",
        "attribution": "Bistritzer and MacDonald predicted the moiré flat-band mechanism; Jarillo-Herrero's group demonstrated correlated insulating and superconducting behavior, connecting the theory to striking experiments.",
        "maturity": "The discovery has rapidly been reproduced and extended to related systems, but the interpretation of phases and the broader scope of the phenomenon are still developing.",
        "uncertainties": [
          "The underlying mechanisms and the extent to which early results generalize remain active research questions."
        ]
      }
    }
  ]
